#!/usr/bin/env bash
# ============================================================================
# LOCAL DATABASE VALIDATION (Phase 2.5 §11)
#
# Builds a throw-away PostgreSQL database, applies:
#   1. the LOCAL auth stub (Supabase-only objects shimmed)
#   2. supabase/migrations/0001..0004
#   3. supabase/seed/0001..0003  (generated by `npm run seed:sql`)
#   4. local table grants
# and then runs supabase/tests/rls_role_matrix.sql with a real
# `authenticated` role and four real users (ADMIN / PROCUREMENT / PIC / VIEWER).
#
# This proves the MIGRATIONS + RLS + TRIGGERS work against real PostgreSQL.
# It does NOT prove Supabase-specific behaviour (auth.users/JWT), which stays
# "NOT YET TESTED" until a real Supabase project exists.
#
# Usage: bash scripts/validate_supabase.sh
# ============================================================================
set -euo pipefail

DB="${DB:-ahs_phase25_validation}"
OUT="${OUT:-docs/_supabase_validation_output.txt}"

run() { psql -v ON_ERROR_STOP=1 -q -d "$DB" -f "$1"; }

echo "==> (re)creating database $DB"
dropdb --if-exists "$DB"
createdb "$DB"

echo "==> auth stub"
run supabase/tests/0000_local_auth_stub.sql

echo "==> migrations"
for m in supabase/migrations/0001_schema.sql \
         supabase/migrations/0002_rls.sql \
         supabase/migrations/0003_protection.sql \
         supabase/migrations/0004_project_sheets.sql; do
  echo "    - $m"
  run "$m"
done

echo "==> seed"
for s in supabase/seed/0001_formula_registry.sql \
         supabase/seed/0002_calculation_templates.sql \
         supabase/seed/0003_template_formulas.sql; do
  echo "    - $s"
  run "$s"
done

echo "==> local grants"
run supabase/tests/0001_local_grants.sql

echo "==> seed integrity"
psql -q -d "$DB" -c "
select 'formula_registry' as obj, count(*) as rows from formula_registry
union all select 'calculation_templates', count(*) from calculation_templates
union all select 'template_formulas', count(*) from template_formulas
union all select 'formula aktif', count(*) from formula_registry where active
union all select 'formula UNRESOLVED & aktif (harus 0)',
                 count(*) from formula_registry where resolution = 'UNRESOLVED' and active
union all select 'template -> formula yatim (harus 0)',
                 count(*) from template_formulas tf
                  left join formula_registry fr on fr.formula_id = tf.formula_id
                  where fr.formula_id is null;
"

echo "==> RLS role matrix"
mkdir -p "$(dirname "$OUT")"
psql -q -d "$DB" -f supabase/tests/rls_role_matrix.sql 2>&1 | tee "$OUT"

echo
echo "==> output saved to $OUT"
